    static int countA, countB, total, maxTransport;
    static long MOD = 1000000007;
    static long[][] nCr = new long[100][100];
    static Map<Integer, Pair> stateMap = new HashMap<>();
    static Queue<Integer> queueStates = new LinkedList<>();
    static class Pair {
        int depth;
        long ways;
        Pair(int d, long w) {
            this.depth = d;
            this.ways = w;
        }
    }
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        total = scanner.nextInt();
        maxTransport = scanner.nextInt();
        countA = 0;
        countB = 0;
        for(int i=0; i<total; i++) {
            int val = scanner.nextInt();
            if(val == 50) countA++;
            else countB++;
        }
        scanner.close();
        initChoose();
        int initialState = 1000000 + 100 * countA + countB;
        queueStates.add(initialState);
        stateMap.put(initialState, new Pair(0, 1));
        while(!queueStates.isEmpty()) {
            processState(queueStates.poll());
        }
        if(stateMap.containsKey(0))
            System.out.println(stateMap.get(0).depth + "\n" + stateMap.get(0).ways);
        else
            System.out.println("-1\n0");
    }
    static void processState(int state) {
        int side = state / 1000000;
        int aCurr = (state % 1000000) / 100;
        int bCurr = state % 100;
        if(side > 0) {
