                }
            }
        }
    }
    static void updateState(int i, int j, int side, int prevState, long edgeWays) {
        int newState = 1000000 * (1 - side) + i * 100 + j;
        int newDepth = stateMap.get(prevState).depth + 1;
        if(!stateMap.containsKey(newState)) {
            stateMap.put(newState, new Pair(newDepth, 0));
            queueStates.add(newState);
        }
        if(stateMap.get(newState).depth == newDepth)
            stateMap.get(newState).ways = (stateMap.get(newState).ways + stateMap.get(prevState).ways * edgeWays % MOD) % MOD;
    }
    static void initChoose() {
