import sys
from collections import deque

MOD = 1000000007
nCr = [[0]*100 for _ in range(100)]
stateMap = {}
queueStates = deque()

class Pair:
    def __init__(self, d, w):
        self.depth = d
        self.ways = w

def initChoose():
    for i in range(100):
        nCr[i][0] = 1
    for i in range(1, 100):
        for j in range(1, i+1):
            nCr[i][j] = (nCr[i-1][j-1] + nCr[i-1][j]) % MOD

def processState(state):
    side = state // 1000000
    aCurr = (state % 1000000) // 100
    bCurr = state % 100
    if side > 0:
        for i in range(aCurr, -1, -1):
            if 50 * (aCurr - i) > maxTransport:
                break
            for j in range(bCurr, -1, -1):
                if 50 * (aCurr - i) + 100 * (bCurr - j) > maxTransport:
                    continue
                if i != aCurr or j != bCurr:
                    updateState(i, j, side, state, nCr[aCurr][i] * nCr[bCurr][j] % MOD)
    else:
        for i in range(aCurr, countA + 1):
            if 50 * (i - aCurr) > maxTransport:
                break
            for j in range(bCurr, countB + 1):
                if 50 * (i - aCurr) + 100 * (j - bCurr) > maxTransport:
                    continue
                if i != aCurr or j != bCurr:
                    updateState(i, j, side, state, nCr[countA - aCurr][i - aCurr] * nCr[countB - bCurr][j - bCurr] % MOD)

def updateState(i, j, side, prevState, edgeWays):
    newState = 1000000 * (1 - side) + i * 100 + j
    newDepth = stateMap[prevState].depth + 1
    if newState not in stateMap:
        stateMap[newState] = Pair(newDepth, 0)
        queueStates.append(newState)
    if stateMap[newState].depth == newDepth:
        stateMap[newState].ways = (stateMap[newState].ways + stateMap[prevState].ways * edgeWays % MOD) % MOD

def main():
    input_data = sys.stdin.read().strip().split()
    total = int(input_data[0])
    maxTransport = int(input_data[1])
    values = list(map(int, input_data[2:]))

    global countA, countB
    countA = 0
    countB = 0
    for val in values:
        if val == 50:
            countA += 1
        else:
            countB += 1

    initChoose()

    initialState = 1000000 + 100 * countA + countB
    stateMap[initialState] = Pair(0, 1)
    queueStates.append(initialState)

    while queueStates:
        current_state = queueStates.popleft()
        processState(current_state)

    if 0 in stateMap:
        print(f"{stateMap[0].depth}\n{stateMap[0].ways}")
    else:
        print("-1\n0")

if __name__ == "__main__":
    main()

